import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AlertTriangle, ArrowRight, BookOpen, Check, Clock3, FileText, GitMerge, Link2, ListFilter, MessageSquare, Plus, RefreshCw, Search, ShieldCheck, X } from 'lucide-react';
import { Badge, Button, Empty, ErrorNotice, FormField, Modal, Spinner, projectPath, Input, Textarea, Select, ControlButton, Disclosure, Tabs, Notice } from './ui.jsx';
import './context.css';
import { useSharedView } from './shared-view.jsx';
import { ContextAI } from './context-ai.jsx';
import { SemanticSearchPanel } from './semantic-search.jsx';
import { ContextInsights } from './insights.jsx';

const KINDS = { requirement: '요구사항', decision: '결정사항', question: '확인할 질문', change: '변경사항', retrospective: '작업 회고', meeting: '회의·대화', knowledge: '프로젝트 지식', note: '업무 메모' };
const SOURCE_TYPES = { revision: '문서·기록', commercial_revision: '계약 문서', work_item: '기능별 작업', channel_inbox: '수집한 대화', context_record: '확정된 기록', candidate: '검토 후보', event: '활동 기록', transcription: '회의 전사', question: '질문·답변', work_artifact: '작업 결과물' };
const CERTAINTIES = { agreed: '고객 합의', ambiguous: '아직 모호함', proposed: '검토 제안' };
const SCOPES = { in_scope: '기존 범위 내', change_request: '변경 요청', unknown: '범위 확인 필요' };
const cleanRefs = (refs = []) => refs.map(({ type, id, sha256 }) => ({ type, id, ...(sha256 ? { sha256 } : {}) }));
const cleanConflicts = (conflicts = []) => conflicts.map(({ record_id, resolution, reason }) => ({ record_id, resolution, reason: reason || '' }));
const STATUS_LABELS = { confirmed: '검토 확정', approved: '승인된 자료', unapproved: '미확정 자료', pending: '검토 대기', merged: '반영 완료', rejected: '반려', replaced: '수정안으로 교체', superseded: '이전 기준', in_progress: '진행 중', evidence_changed: '근거 변경 확인 필요', recorded: '원문 기록', ready: '추출된 원문', transcribed: '전사 원문', accepted: '검토한 대화', todo: '작업 대기', done: '작업 완료', blocked: '작업 보류', needs_review: '검토 필요' };
const EMPTY = [];
const dayKst = (value = new Date()) => new Date(new Date(value).getTime() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10);
// 09:00 KST is midnight UTC; before 09:00 use the previous completed window.
const latestReportDay = () => new Date().toISOString().slice(0, 10);
const nowKst = () => new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 19);
const isoKst = (value) => value ? new Date(`${value}+09:00`).toISOString() : null;
const localKst = (value) => value ? new Date(new Date(value).getTime() + 9 * 60 * 60 * 1000).toISOString().slice(0, 19) : nowKst();
const preciseTime = (value) => {
  if (!value || Number.isNaN(new Date(value).getTime())) return '시각 미기록';
  return new Intl.DateTimeFormat('ko-KR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Seoul' }).format(new Date(value));
};
const occurredLabel = (source) => source.occurred_time_source === 'date_only' ? `${dayKst(source.occurred_at)} · 날짜만 기록` : source.occurred_time_source === 'recorded_fallback' ? `${preciseTime(source.occurred_at)} · 등록 시각 기준` : preciseTime(source.occurred_at);
const safeUrl = (value) => { try { const url = new URL(value); return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password ? url.href : null; } catch { return null; } };
const sourceKey = (ref) => `${ref.type}:${ref.id}`;
const emptyDraft = (kind = 'meeting', version = 0) => ({ request_id: crypto.randomUUID(), kind, title: '', body: '', rationale: '', alternatives: [], domain_id: '', entity_key: '', occurred_at: nowKst(), channel: kind === 'retrospective' ? '업무 회고' : '회의록', source_refs: [], questions: [], conflicts: [], supersedes_id: '', expected_context_version: version, reuse_scope: 'project', certainty: 'proposed', scope: 'unknown' });
const isDraftDirty = (draft) => Boolean(draft && (draft.title.trim() || draft.body.trim() || draft.rationale.trim() || draft.source_refs.length || draft.alternatives.length || draft.questions.length || draft.conflicts.length || draft.entity_key.trim() || draft.supersedes_id));

function useContextData(request, url, revision) {
  const [state, setState] = useState({ data: null, loading: true, error: null });
  const sequence = useRef(0);
  useEffect(() => {
    const controller = new AbortController(), id = ++sequence.current;
    if (!url) { setState({ data: null, loading: false, error: null }); return () => controller.abort(); }
    setState((old) => ({ ...old, loading: true, error: null }));
    request(url, { signal: controller.signal }).then((data) => { if (id === sequence.current) setState({ data, loading: false, error: null }); }).catch((error) => { if (error.name !== 'AbortError' && id === sequence.current) setState((old) => ({ ...old, error, loading: false })); });
    return () => { sequence.current += 1; controller.abort(); };
  }, [request, url, revision]);
  return state;
}

function ContextStatus({ status, approved }) {
  const value = approved === false && ['approved', 'confirmed'].includes(status) ? 'evidence_changed' : status || (approved ? 'approved' : 'unapproved');
  return <Badge tone={['confirmed', 'approved', 'merged'].includes(value) ? 'green' : ['pending', 'unapproved', 'evidence_changed'].includes(value) ? 'amber' : value === 'rejected' ? 'red' : 'quiet'}>{STATUS_LABELS[value] || value}</Badge>;
}

function SourceLink({ source, onOpenRecord, onOpenWorkItem, children }) {
  const ref = source.internal_ref || source;
  const url = safeUrl(source.url);
  if (url) return <Button asChild variant="ghost"><a href={url} target="_blank" rel="noopener noreferrer"><Link2 size={13} />{children || '원본 열기'}</a></Button>;
  if (ref.type === 'work_item' && onOpenWorkItem) return <ControlButton className="text-button" type="button" onClick={() => onOpenWorkItem(ref.id)}><Link2 size={13} />{children || '작업 열기'}</ControlButton>;
  if (onOpenRecord && ['revision', 'commercial_revision', 'channel_inbox', 'context_record', 'candidate'].includes(ref.type)) return <ControlButton className="text-button" type="button" onClick={() => onOpenRecord(ref)}><Link2 size={13} />{children || '근거 열기'}</ControlButton>;
  return <span className="ctx-source-label"><FileText size={13} />{children || SOURCE_TYPES[ref.type] || '프로젝트 기록'}</span>;
}

export function MainContextWorkspace({ project, domains = EMPTY, request, canWrite, canReview, onChanged, notify, onOpenRecord, onOpenWorkItem, onDirty, initialView = 'context', initialCandidateId }) {
  const sharedView = useSharedView();
  const route = `${projectPath(project.id)}/context`;
  const [aiDirty, setAiDirty] = useState(false), [insightDirty, setInsightDirty] = useState(false);
  const [knowledgeOpen, setKnowledgeOpen] = useState(false), [knowledgeDraft, setKnowledgeDraft] = useState(null);
  const [revision, setRevision] = useState(0), [tab, setTab] = useState(initialView), [domain, setDomain] = useState(''), [kind, setKind] = useState(''), [certainty, setCertainty] = useState(''), [scope, setScope] = useState('');
  const [queryInput, setQueryInput] = useState(''), [query, setQuery] = useState(''), [includeUnapproved, setIncludeUnapproved] = useState(false), [offset, setOffset] = useState(0);
  const [reportDate, setReportDate] = useState(latestReportDay), [timelineOffset, setTimelineOffset] = useState(0);
  const [evidenceError, setEvidenceError] = useState(null), evidenceSequence = useRef(0);
  const [replaceDraft, setReplaceDraft] = useState(null);
  const [draft, setDraft] = useState(null), [editorOpen, setEditorOpen] = useState(false), [selected, setSelected] = useState(null), [reviewReasons, setReviewReasons] = useState({});
  const summary = useContextData(request, route, revision);
  const data = summary.data;
  const records = data?.records || EMPTY, candidates = data?.candidates || EMPTY;
  const sourceParams = new URLSearchParams({ query, include_unapproved: String(includeUnapproved), limit: '20', offset: String(offset), ...(domain ? { domain_id: domain } : {}) });
  const search = useContextData(request, tab === 'context' ? `${route}/search?${sourceParams}` : null, revision);
  const startDay = new Date(new Date(`${reportDate}T00:00:00Z`).getTime() - 86400000).toISOString().slice(0, 10);
  const timelineParams = new URLSearchParams({ start: `${startDay}T09:00:00+09:00`, end: `${reportDate}T09:00:00+09:00`, limit: '50', offset: String(timelineOffset), ...(domain ? { domain_id: domain } : {}) });
  const timeline = useContextData(request, tab === 'timeline' ? `${route}/timeline?${timelineParams}` : null, revision);
  const visibleRecords = records.filter((item) => (!domain || item.domain_id === domain) && (!kind || item.kind === kind) && (!certainty || item.certainty === certainty) && (!scope || item.scope === scope) && item.status !== 'superseded');
  const pending = candidates.filter((item) => item.status === 'pending');
  const visibleCandidates = pending.filter((item) => !domain || item.domain_id === domain);
  const knowledge = records.filter((item) => item.kind === 'knowledge' && (!domain || item.domain_id === domain) && item.status !== 'superseded');
  const pendingKnowledge = visibleCandidates.filter((item) => item.kind === 'knowledge');
  const dirty = aiDirty || insightDirty || Boolean(knowledgeDraft?.source_record_id) || isDraftDirty(draft) || Object.values(reviewReasons).some((reason) => reason.trim());
  useEffect(() => { onDirty?.(dirty); }, [dirty, onDirty]);
  useEffect(() => () => onDirty?.(false), [onDirty]);
  useEffect(() => () => { evidenceSequence.current += 1; }, []);
  const refresh = useCallback(() => setRevision((value) => value + 1), []);
  async function changed(message) { refresh(); notify?.(message); await Promise.allSettled([Promise.resolve().then(() => onChanged?.({ quiet: true }))]); }
  function openEditor(nextKind = 'meeting', original, fromRecord = false) {
    if (original) setDraft({ ...emptyDraft(original.kind, data?.version || 0), ...original, request_id: crypto.randomUUID(), occurred_at: localKst(original.occurred_at), expected_context_version: data?.version || 0, source_refs: cleanRefs(original.source_refs), alternatives: original.alternatives || [], questions: original.questions || [], conflicts: cleanConflicts(original.conflicts), domain_id: original.domain_id || '', entity_key: original.entity_key || '', supersedes_id: fromRecord ? original.id : original.supersedes_id || '', based_on_candidate: fromRecord ? undefined : original.id, from_record: fromRecord, expected_candidate_sha256: fromRecord ? undefined : original.content_sha256 });
    else if (!draft) setDraft(emptyDraft(nextKind, data?.version || 0));
    setEditorOpen(true);
  }
  async function openEvidence(ref) {
    const sequence = ++evidenceSequence.current; setEvidenceError(null);
    try {
      if (ref.type === 'context_record' || ref.type === 'candidate') {
        const candidate = ref.type === 'candidate';
        const result = await request(`${route}/${candidate ? 'candidates' : 'records'}/${encodeURIComponent(ref.id)}`);
        if (sequence === evidenceSequence.current) setSelected({ type: candidate ? 'candidate' : 'record', item: candidate ? result.candidate : result.record });
      } else if (['revision', 'commercial_revision', 'work_item', 'channel_inbox', 'transcription', 'question', 'work_artifact'].includes(ref.type)) {
        if (sequence === evidenceSequence.current) setSelected({ type: 'source', item: ref });
      } else onOpenRecord?.(ref);
    } catch (error) { if (sequence === evidenceSequence.current) setEvidenceError(error); }
  }
  useEffect(() => {
    if (!initialCandidateId) return;
    const controller = new AbortController();
    request(`${route}/candidates/${encodeURIComponent(initialCandidateId)}`, { signal: controller.signal })
      .then(result => { if (!controller.signal.aborted) setSelected({type:'candidate', item:result.candidate}); })
      .catch(error => { if (!controller.signal.aborted) setEvidenceError(error); });
    return () => controller.abort();
  }, [route, initialCandidateId, request]);
  const sourceProps = { onOpenRecord: openEvidence, onOpenWorkItem };
  return <section className="ctx-workspace"><Tabs value={tab} onValueChange={setTab} variant="underline" size="sm" data-ctds="tabs">
    <div className="ctx-intro"><div className="ctx-intro-actions">{!sharedView ? <Button icon={Plus} onClick={() => openEditor()} disabled={!canWrite || !data}>{isDraftDirty(draft) ? '작성 중인 기록 이어쓰기' : '회의·작업 기록 작성'}</Button> : null}<span>확정 기록 v{data?.version ?? '—'}</span></div></div>
    <ErrorNotice error={summary.error} onRetry={refresh} /><ErrorNotice error={evidenceError} />
    <div className="ctx-metrics" aria-label="프로젝트 맥락 현황">{[['context', '검토 확정', data?.counts?.records ?? records.length, '근거와 함께 남긴 기준'], ['review', '검토 대기', data?.counts?.candidates ?? pending.length, '확정 전 확인할 내용'], ['context', '질문 기록', data?.counts?.questions ?? 0, '추가 확인할 질문과 맥락'], ['knowledge', '프로젝트 지식', data?.counts?.knowledge ?? knowledge.length, '검토한 경험과 해결 방식']].map(([target, label, count, desc]) => <ControlButton key={label} onClick={() => { setTab(target); if (label === '질문 기록') setKind('question'); else if (target === 'context') setKind(''); }}><span>{label}</span><strong>{summary.loading && !data ? '—' : count}</strong><small>{desc}</small><ArrowRight size={14} /></ControlButton>)}</div>
    <div className="ctx-navigation"><Tabs.List aria-label="요구사항·결정 보기">{[['context', '검색·확정 기록', BookOpen], ['semantic', '의미 검색', Search], ['insights', '리스크·회고', AlertTriangle], ['timeline', '일별 변화', Clock3], ['ai', 'Nora 분석', MessageSquare], ['review', '검토함', GitMerge], ['knowledge', '재사용 자료', ShieldCheck]].filter(([id]) => !sharedView || !['semantic', 'insights', 'ai'].includes(id)).map(([id, label, Icon]) => <Tabs.Trigger key={id} value={id} leadingIcon={<Icon />}>{label}{id === 'review' && pending.length ? <span>{data?.counts?.candidates ?? pending.length}</span> : null}</Tabs.Trigger>)}</Tabs.List><div className="ctx-domain"><label htmlFor="ctx-domain">업무 영역</label><Select id="ctx-domain" value={domain} onChange={(event) => { setDomain(event.target.value); setOffset(0); setTimelineOffset(0); }}><option value="">프로젝트 전체</option>{domains.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select><ControlButton type="button" className="icon-button" onClick={refresh} aria-label="요구사항·결정 새로고침" disabled={summary.loading}><RefreshCw size={16} /></ControlButton></div></div>
    <Tabs.Panel value={tab}>{summary.loading && !data ? <Spinner label="프로젝트의 맥락을 모으고 있습니다" /> : !data ? null : <>
      <ContextAI active={tab === 'ai'} route={route} request={request} version={data.version} domainId={domain} canWrite={canWrite} canReview={canReview} onChanged={changed} onOpenSource={openEvidence} onDirty={setAiDirty} />
      {!sharedView && tab === 'semantic' ? <SemanticSearchPanel project={project} request={request} canReview={canReview} domains={domains} onOpenSource={openEvidence} notify={notify}/> : null}
      <div hidden={tab !== 'insights'}><ContextInsights project={project} request={request} canWrite={canWrite} canReview={canReview} version={data.version} onOpenSource={openEvidence} onChanged={changed} notify={notify} onDirty={setInsightDirty}/></div>
      {tab === 'context' ? <><section className="ctx-search-panel"><form className="ctx-search" onSubmit={(event) => { event.preventDefault(); setQuery(queryInput.trim()); setOffset(0); }}><Search size={19} /><label className="sr-only" htmlFor="ctx-query">프로젝트 자료 검색</label><Input id="ctx-query" value={queryInput} onChange={(event) => setQueryInput(event.target.value)} placeholder="요구사항, 결정, 문서·대화의 키워드를 검색하세요" maxLength={500} /><Button type="submit" busy={search.loading}>찾기</Button></form><div className="ctx-search-meta"><label><Input type="checkbox" checked={includeUnapproved} onChange={(event) => { setIncludeUnapproved(event.target.checked); setOffset(0); }} />미확정 원문·검토 후보도 포함</label><span>현재 프로젝트의 키워드 검색 · 원문 근거 연결</span></div><ErrorNotice error={search.error} onRetry={refresh} />{search.loading ? <Spinner label="관련 자료를 찾고 있습니다" /> : search.data?.items?.length ? <><div className="ctx-search-results">{search.data.items.map((source) => <SourceCard key={sourceKey(source.internal_ref || source)} source={source} {...sourceProps} />)}</div><Pagination offset={offset} pageSize={20} data={search.data} setOffset={setOffset} /></> : search.error ? null : <Empty compact icon={Search} title={query ? '조건에 맞는 자료가 없습니다' : '검색할 확정 자료가 없습니다'}>{includeUnapproved ? '문서·기록을 등록하거나 다른 키워드로 검색해 주세요.' : '미확정 원문도 포함하면 등록된 자료와 검토 후보를 함께 찾을 수 있습니다.'}</Empty>}</section><section className="ctx-records"><div className="ctx-section-heading"><div><h3>확정된 요구사항·결정</h3></div><div className="ctx-record-filters"><label><ListFilter size={14} /><span className="sr-only">기록 종류</span><Select value={kind} onChange={(event) => setKind(event.target.value)}><option value="">모든 종류</option>{Object.entries(KINDS).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</Select></label><label><span className="sr-only">합의 상태 필터</span><Select value={certainty} onChange={(event) => setCertainty(event.target.value)}><option value="">모든 합의 상태</option>{Object.entries(CERTAINTIES).map(([id, label]) => <option value={id} key={id}>{label}</option>)}</Select></label><label><span className="sr-only">계약 범위 필터</span><Select value={scope} onChange={(event) => setScope(event.target.value)}><option value="">모든 범위 판단</option>{Object.entries(SCOPES).map(([id, label]) => <option value={id} key={id}>{label}</option>)}</Select></label></div></div><p className="ctx-help">사람이 검토한 내용입니다. 고객과의 합의 여부는 각 기록의 결정 근거를 확인하세요.</p>{visibleRecords.length ? <div className="ctx-record-grid">{visibleRecords.map((item) => <RecordCard key={item.id} item={item} domains={domains} onClick={() => setSelected({ type: 'record', item })} />)}</div> : <Empty compact icon={BookOpen} title="아직 확정한 기록이 없습니다">회의나 작업 기록을 검토함에 등록하고, 근거를 확인한 뒤 프로젝트 기록으로 확정하세요.</Empty>}{data.has_more?.records ? <p className="ctx-help">최근 확정 기록 100건을 표시합니다. 이전 기록은 위 검색에서 찾아주세요.</p> : null}</section></> : null}
      {tab === 'timeline' ? <section className="ctx-timeline"><div className="ctx-section-heading"><div><h3>{startDay} 09:00 — {reportDate} 09:00</h3><p className="ctx-help">발생 시각 기준 · 종료 시각은 다음 기간에 포함합니다. 발생 시각이 없으면 등록 시각 기준임을 표시합니다.</p></div><FormField label="조회 종료일 (한국 시간)"><Input type="date" value={reportDate} required onChange={(event) => { if (event.target.value) { setReportDate(event.target.value); setTimelineOffset(0); } }} /></FormField></div><ErrorNotice error={timeline.error} onRetry={refresh} />{timeline.loading ? <Spinner label="하루 동안의 변화를 모으고 있습니다" /> : timeline.data?.items?.length ? <><ol className="ctx-timeline-list">{timeline.data.items.map((item) => <li key={`${item.source_type}:${item.id}`}><div className="ctx-timeline-time"><time dateTime={item.occurred_at}>{occurredLabel(item)}</time><small>{item.occurred_time_source === 'recorded_fallback' ? '등록 시각으로 표시' : item.occurred_time_source === 'date_only' ? '발생 날짜' : '발생'}</small></div><article><header><span>{KINDS[item.kind] || SOURCE_TYPES[item.source_type] || '프로젝트 활동'}</span>{item.status ? <ContextStatus status={item.status} /> : null}</header><h4>{item.title}</h4>{item.text ? <p>{item.text}</p> : null}<footer><small>등록 {preciseTime(item.recorded_at)}</small><SourceLink source={item} {...sourceProps} /></footer></article></li>)}</ol><Pagination offset={timelineOffset} pageSize={50} data={timeline.data} setOffset={setTimelineOffset} /></> : timeline.error ? null : <Empty icon={Clock3} title="이 기간에 발생한 기록이 없습니다">종료일을 변경하거나 회의·업무 기록의 발생 시각을 확인해 주세요.</Empty>}</section> : null}
      {tab === 'review' ? <section className="ctx-review"><div className="ctx-section-heading"><div><h3>검토 후 프로젝트 기록으로 확정</h3></div>{!sharedView ? <Button variant="secondary" icon={Plus} disabled={!canWrite} onClick={() => openEditor('decision')}>결정·변경 기록</Button> : null}</div><div className="ctx-review-note"><ShieldCheck size={19} /><p>원문 등록과 검색은 바로 이용할 수 있습니다. 의미를 정리한 결정·요구사항·지식은 근거와 미해결 질문을 확인한 뒤 확정합니다.</p></div>{visibleCandidates.length ? <div className="ctx-candidate-list">{visibleCandidates.map((item) => <ControlButton key={item.id} onClick={() => setSelected({ type: 'candidate', item })}><span className="ctx-candidate-icon"><GitMerge size={19} /></span><div><span>{KINDS[item.kind] || item.kind} · {domains.find((entry) => entry.id === item.domain_id)?.name || '프로젝트 공통'}</span><h4>{item.title}</h4><p>{item.body}</p><small>발생 {preciseTime(item.occurred_at)} · 등록 {preciseTime(item.created_at)}</small></div><div className="ctx-candidate-flags"><ContextStatus status={item.status} />{item.conflicts?.some((entry) => entry.resolution === 'unresolved') ? <Badge tone="red">충돌 확인</Badge> : null}{item.questions?.some((entry) => entry.blocking && !entry.answer?.trim()) ? <Badge tone="amber">답변 필요</Badge> : null}{item.base_version !== data.version ? <Badge tone="amber">기준 갱신 필요</Badge> : null}</div><ArrowRight size={16} /></ControlButton>)}</div> : <Empty icon={GitMerge} title="현재 검토할 기록이 없습니다">회의·작업 내용을 기록하거나 기존 자료를 근거로 결정사항을 제안하세요.</Empty>}{data.has_more?.candidates ? <p className="ctx-help">최근 검토 후보 100건입니다. 이전 후보는 미확정 자료를 포함한 검색에서 확인하세요.</p> : null}</section> : null}
      {tab === 'knowledge' ? <section><div className="ctx-section-heading"><div><h3>다시 꺼내 쓸 경험과 판단</h3></div>{!sharedView ? <div className="inline-actions"><Button variant="secondary" disabled={!canWrite} onClick={() => { if (!knowledgeDraft) setKnowledgeDraft({ request_id: crypto.randomUUID(), source_project_id: '', source_record_id: '', source_sha256: '', expected_context_version: data.version, title: '', body: '', rationale: '', domain_id: domain, occurred_at: nowKst() }); setKnowledgeOpen(true); }}>다른 프로젝트 지식 가져오기</Button><Button variant="secondary" icon={Plus} disabled={!canWrite} onClick={() => openEditor('knowledge')}>지식 후보 작성</Button></div> : null}</div><div className="ctx-knowledge-boundary"><BookOpen size={22} /><div><strong>현재 프로젝트 안에서 재사용합니다.</strong><p>문제 상황, 채택·폐기한 대안, 해결 근거를 검토해 남깁니다. 다른 프로젝트의 지식은 원본 검토 권한을 확인하고 공유할 내용을 골라 가져옵니다.</p></div><Badge tone="quiet">프로젝트 한정</Badge></div>{knowledge.length ? <div className="ctx-record-grid">{knowledge.map((item) => <RecordCard key={item.id} item={item} domains={domains} onClick={() => setSelected({ type: 'record', item })} />)}</div> : <Empty icon={BookOpen} title="검토한 프로젝트 지식이 없습니다">완료한 작업의 결과와 판단 이유를 지식 후보로 남겨주세요. 검토자가 확인하면 이곳에 모입니다.</Empty>}{!sharedView && pendingKnowledge.length ? <><div className="ctx-section-heading"><div><h3>검토 대기 지식</h3><p>내용과 출처를 검토하면 재사용 자료로 확정할 수 있습니다.</p></div></div><div className="ctx-candidate-list">{pendingKnowledge.map((item) => <ControlButton key={item.id} type="button" onClick={() => setSelected({ type: 'candidate', item })}><div><strong>{item.title}</strong><p>{item.body}</p><Badge tone="amber">검토 대기</Badge></div><ArrowRight size={16} /></ControlButton>)}</div></> : null}</section> : null}
      <p className="ctx-capability-note">원문과 검토한 결정을 함께 연결합니다. 외부 채널은 연결 범위에 따라 수집하고, 의미 검색·회의 전사는 프로젝트 AI 설정을 사용합니다.</p>
    </>}</Tabs.Panel>
    {editorOpen && draft ? <ContextEditor draft={draft} setDraft={setDraft} route={route} request={request} records={records} domains={domains} version={data?.version || 0} onClose={() => setEditorOpen(false)} onDiscard={() => { setDraft(null); setEditorOpen(false); }} onDone={async () => { if (draft?.based_on_candidate) setReviewReasons((old) => { const next = { ...old }; delete next[draft.based_on_candidate]; return next; }); setDraft(null); setEditorOpen(false); setTab('review'); await changed('검토 후보로 등록했습니다. 확인 후 프로젝트 기록으로 확정할 수 있습니다.'); }} /> : null}
    {selected?.type === 'source' ? <ContextSourceDetail key={sourceKey(selected.item)} route={route} request={request} sourceRef={selected.item} onClose={() => setSelected(null)} onOpenRecord={onOpenRecord} onOpenWorkItem={onOpenWorkItem} /> : selected ? <ContextDetail key={selected.item.id} selected={selected} records={records} version={data?.version || 0} route={route} request={request} domains={domains} canWrite={canWrite} canReview={canReview} sourceProps={sourceProps} reason={reviewReasons[selected.item.id] || ''} onReason={(reason) => setReviewReasons((old) => ({ ...old, [selected.item.id]: reason }))} onClose={() => setSelected(null)} onRefine={(item) => { setSelected(null); if (isDraftDirty(draft)) setReplaceDraft({ item, fromRecord: selected.type === 'record' }); else openEditor(item.kind, item, selected.type === 'record'); }} onDone={async (message) => { setReviewReasons((old) => { const next = { ...old }; delete next[selected.item.id]; return next; }); setSelected(null); await changed(message); }} /> : null}
    {knowledgeOpen && knowledgeDraft ? <KnowledgeImport project={project} request={request} route={route} version={data?.version || 0} domains={domains} draft={knowledgeDraft} setDraft={setKnowledgeDraft} onClose={() => setKnowledgeOpen(false)} onDiscard={() => { setKnowledgeOpen(false); setKnowledgeDraft(null); }} onDone={async () => { setKnowledgeOpen(false); setKnowledgeDraft(null); setTab('review'); await changed('다른 프로젝트의 지식을 검토 후보로 가져왔습니다. 적용 범위를 확인한 뒤 확정하세요.'); }} /> : null}
    {replaceDraft ? <Modal title="작성 중인 기록이 있습니다" onClose={() => setReplaceDraft(null)}><div className="modal-body"><p className="form-intro">기존 작성 내용을 유지하거나, 비우고 선택한 검토 후보의 수정안을 작성할 수 있습니다.</p></div><footer className="modal-actions"><Button variant="secondary" onClick={() => { setReplaceDraft(null); setEditorOpen(true); }}>기존 기록 이어쓰기</Button><Button onClick={() => { const { item, fromRecord } = replaceDraft; setReplaceDraft(null); openEditor(item.kind, item, fromRecord); }}>기존 초안 비우고 수정안 작성</Button></footer></Modal> : null}
  </Tabs></section>;
}

function Pagination({ offset, pageSize, data, setOffset }) {
  if (!offset && !data.has_more) return null;
  return <div className="ctx-pagination"><span>{offset + 1}–{offset + (data.items?.length || 0)} / {data.total}건</span><Button type="button" variant="secondary" onClick={() => setOffset(Math.max(0, offset - pageSize))} disabled={!offset}>이전</Button><Button type="button" variant="secondary" onClick={() => setOffset(offset + pageSize)} disabled={!data.has_more}>다음</Button></div>;
}

function SourceCard({ source, ...sourceProps }) {
  return <article className="ctx-source-card"><header><span>{SOURCE_TYPES[source.internal_ref?.type || source.type] || '프로젝트 자료'}</span><ContextStatus status={source.status} approved={source.approved} /></header><h4>{source.title}</h4><p>{source.text || '본문은 원본에서 확인하세요.'}</p><footer><span>발생 {occurredLabel(source)}<small>등록 {preciseTime(source.recorded_at)}</small></span><SourceLink source={source} {...sourceProps} /></footer></article>;
}

function RecordCard({ item, domains, onClick }) {
  return <ControlButton className="ctx-record-card" onClick={onClick}><header><span>{KINDS[item.kind] || item.kind}</span><span>v{item.context_version}</span></header>{item.evidence_changed ? <Badge tone="amber">근거 변경 확인 필요</Badge> : null}<h4>{item.title}</h4><p>{item.body}</p><footer><span>{domains.find((entry) => entry.id === item.domain_id)?.name || '프로젝트 공통'}</span><span>근거 {item.source_refs?.length || 0}개<ArrowRight size={13} /></span></footer></ControlButton>;
}

function ContextDetail({ selected, records, version, route, request, domains, canWrite, canReview, sourceProps, reason, onReason, onClose, onRefine, onDone }) {
  const item = selected.item, review = selected.type === 'candidate' && item.status === 'pending';
  const [busy, setBusy] = useState(false), [error, setError] = useState(null), [acknowledged, setAcknowledged] = useState(false);
  const previous = records.find((entry) => entry.id === item.supersedes_id) || records.find((entry) => item.conflicts?.some((conflict) => conflict.record_id === entry.id));
  const blockedQuestion = item.questions?.some((entry) => entry.blocking && !entry.answer?.trim());
  const unresolved = item.conflicts?.some((entry) => entry.resolution === 'unresolved');
  const stale = review && item.base_version !== version;
  async function decide(decision) {
    setBusy(true); setError(null);
    try { await request(`${route}/candidates/${encodeURIComponent(item.id)}/decision`, { method: 'POST', body: { decision, reason: reason.trim(), expected_context_version: version, expected_candidate_sha256: item.content_sha256 } }); await onDone(decision === 'merged' ? '검토한 내용을 프로젝트 기록으로 확정했습니다.' : '검토 후보를 반려했습니다. 원문과 검토 이력은 보존됩니다.'); }
    catch (err) { setError(err); } finally { setBusy(false); }
  }
  return <Modal title={item.title} eyebrow={`${KINDS[item.kind] || item.kind} · ${review ? '기록 검토' : 'CONTEXT RECORD'}`} wide busy={busy} onClose={onClose}><div className="modal-body ctx-detail"><div className="ctx-detail-meta"><ContextStatus status={item.status} /><span>{domains.find((entry) => entry.id === item.domain_id)?.name || '프로젝트 공통'}</span><span>{item.channel || '채널 미기록'}</span><Badge tone={item.certainty === 'agreed' ? 'green' : 'amber'}>{CERTAINTIES[item.certainty] || '검토 제안'}</Badge><Badge tone={item.scope === 'in_scope' ? 'quiet' : 'amber'}>{SCOPES[item.scope] || '범위 확인 필요'}</Badge></div><dl className="ctx-time-fields"><dt>발생·결정 시각</dt><dd>{preciseTime(item.occurred_at)} KST</dd><dt>등록 시각</dt><dd>{preciseTime(item.created_at)} KST</dd></dl>
    {previous ? <div className="ctx-diff"><section><span>기존 기준 · v{previous.context_version}</span><h4>{previous.title}</h4><p>{previous.body}</p></section><section><span>{review ? '반영할 내용' : '확정한 내용'}</span><h4>{item.title}</h4><p>{item.body}</p></section></div> : <div className="ctx-body-text">{item.body}</div>}
    <section className="ctx-detail-section"><h4>판단 이유·근거</h4><p>{item.rationale || '별도 판단 이유가 기록되지 않았습니다.'}</p></section>
    {item.alternatives?.length ? <section className="ctx-detail-section"><h4>검토한 대안</h4><ul className="ctx-alternatives">{item.alternatives.map((entry, index) => <li key={index}><Badge tone={entry.status === 'chosen' ? 'green' : 'quiet'}>{{ chosen: '채택', rejected: '폐기', deferred: '보류' }[entry.status]}</Badge><div><strong>{entry.title}</strong><p>{entry.reason}</p></div></li>)}</ul></section> : null}
    {item.questions?.length ? <section className="ctx-detail-section"><h4>확인할 질문</h4>{item.questions.map((entry, index) => <div key={index} className="ctx-question"><strong>{entry.text}</strong><Badge tone={entry.answer?.trim() ? 'green' : entry.blocking ? 'amber' : 'quiet'}>{entry.answer?.trim() ? '답변 기록됨' : entry.blocking ? '확정 전 답변 필요' : '후속 확인'}</Badge><p>{entry.answer || '아직 답변이 없습니다.'}</p></div>)}</section> : null}
    {item.conflicts?.length ? <section className="ctx-detail-section"><h4>기존 기준과의 충돌 검토</h4>{item.conflicts.map((entry, index) => <div key={index} className="ctx-question"><strong>{records.find((record) => record.id === entry.record_id)?.title || '연결된 기존 기준'}</strong><Badge tone={entry.resolution === 'unresolved' ? 'red' : 'green'}>{{ unresolved: '미해결', supersede: '기존 기준 대체', coexist: '적용 조건을 나눠 유지' }[entry.resolution]}</Badge><p>{entry.reason || '충돌 해결 근거를 작성해 주세요.'}</p></div>)}</section> : null}
    <section className="ctx-detail-section"><h4>원문 근거 {item.source_refs?.length || 0}개</h4>{item.source_refs?.length ? <div className="ctx-evidence-links">{item.source_refs.map((ref) => <SourceLink key={sourceKey(ref)} source={ref} {...sourceProps}>{ref.title || SOURCE_TYPES[ref.type] || '연결한 근거'}</SourceLink>)}</div> : <p>담당자가 직접 작성한 내용입니다. 외부 원문 근거는 연결되지 않았습니다.</p>}</section>
    {review ? <section className="ctx-merge-panel"><h4>검토 결과</h4>{stale || unresolved || blockedQuestion ? <Notice className="notice warning"><AlertTriangle size={17} /><p>{stale ? '등록 이후 프로젝트 기준이 변경되었습니다. 최신 기준으로 수정안을 작성해 주세요. ' : ''}{unresolved ? '충돌 해결 방법과 근거를 수정안에 기록해 주세요. ' : ''}{blockedQuestion ? '확정에 필요한 질문의 답변을 수정안에 기록해 주세요.' : ''}</p></Notice> : null}{canWrite ? <Button type="button" variant="secondary" onClick={() => onRefine(item)} disabled={busy}>수정안 작성</Button> : null}<FormField label="검토 의견" hint="확정 또는 반려한 이유를 남깁니다."><Textarea value={reason} onChange={(event) => onReason(event.target.value)} rows={3} maxLength={5000} disabled={!canReview || busy} placeholder="원문 근거와 적용 조건을 확인한 결과" /></FormField><label className="ctx-check"><Input type="checkbox" checked={acknowledged} onChange={(event) => setAcknowledged(event.target.checked)} disabled={!canReview || busy} />내용·근거·기존 기준과의 관계를 확인했습니다.</label>{!canReview ? <p className="ctx-help">검토자 또는 관리자가 확정할 수 있습니다.</p> : null}</section> : null}<ErrorNotice error={error} /></div><footer className="modal-actions"><Button variant="secondary" type="button" onClick={onClose} disabled={busy}>닫기</Button>{!review && selected.type === 'record' && canWrite ? <Button variant="secondary" type="button" onClick={() => onRefine(item)}>후속 변경·답변 기록</Button> : null}{review && canReview ? <><Button variant="secondary" type="button" disabled={busy || !reason.trim()} onClick={() => decide('rejected')}>반려</Button><Button icon={Check} type="button" busy={busy} disabled={!acknowledged || !reason.trim() || stale || unresolved || blockedQuestion} onClick={() => decide('merged')}>{item.kind === 'knowledge' ? '프로젝트 지식으로 확정' : '프로젝트 기록으로 확정'}</Button></> : null}</footer></Modal>;
}

function ContextEditor({ draft, setDraft, route, request, records, domains, version, onClose, onDiscard, onDone }) {
  const [busy, setBusy] = useState(false), [error, setError] = useState(null), [sourceQuery, setSourceQuery] = useState(''), [sourceSearch, setSourceSearch] = useState(''), [sourceOffset, setSourceOffset] = useState(0);
  const attempted = Boolean(draft.submitted_payload);
  const sources = useContextData(request, `${route}/sources?${new URLSearchParams({ query: sourceSearch, limit: '10', offset: String(sourceOffset), ...(draft.domain_id ? { domain_id: draft.domain_id } : {}) })}`, 0);
  const selectedRefs = useMemo(() => new Set(draft.source_refs.map(sourceKey)), [draft.source_refs]);
  const potentialConflicts = records.filter((item) => item.status !== 'superseded' && draft.entity_key.trim() && item.entity_key === draft.entity_key.trim() && (item.domain_id || '') === draft.domain_id);
  const locked = busy || attempted;
  function update(field, value) { setDraft((old) => ({ ...old, [field]: value })); }
  function updateEntry(field, index, key, value) { update(field, draft[field].map((entry, i) => i === index ? { ...entry, [key]: value } : entry)); }
  function removeEntry(field, index) { update(field, draft[field].filter((_, i) => i !== index)); }
  function chooseSource(source) { const ref = source.internal_ref || { type: source.type, id: source.id }; const key = sourceKey(ref); update('source_refs', selectedRefs.has(key) ? draft.source_refs.filter((entry) => sourceKey(entry) !== key) : [...draft.source_refs, { type: ref.type, id: ref.id, ...(source.sha256 ? { sha256: source.sha256 } : {}) }]); }
  function conflictValue(recordId) { return draft.conflicts.find((entry) => entry.record_id === recordId) || { record_id: recordId, resolution: 'unresolved', reason: '' }; }
  function changeConflict(recordId, key, value) { const current = conflictValue(recordId); update('conflicts', [...draft.conflicts.filter((entry) => entry.record_id !== recordId), { ...current, [key]: value }]); }
  const conflictIds = [...new Set([...potentialConflicts.map((item) => item.id), ...draft.conflicts.map((item) => item.record_id)])];
  async function submit(event) {
    event.preventDefault(); setBusy(true); setError(null);
    const payload = draft.submitted_payload || { request_id: draft.request_id, kind: draft.kind, title: draft.title.trim(), body: draft.body.trim(), rationale: draft.rationale.trim(), alternatives: draft.alternatives, domain_id: draft.domain_id || null, entity_key: draft.entity_key.trim() || null, occurred_at: isoKst(draft.occurred_at), channel: draft.channel.trim(), source_refs: cleanRefs(draft.source_refs), questions: draft.questions, conflicts: cleanConflicts(conflictIds.map(conflictValue)), supersedes_id: draft.supersedes_id || null, expected_context_version: draft.expected_context_version, reuse_scope: 'project', certainty: draft.certainty || 'proposed', scope: draft.scope || 'unknown', ...(draft.based_on_candidate ? { expected_candidate_sha256: draft.expected_candidate_sha256 } : {}) };
    update('submitted_payload', payload);
    try { await request(draft.based_on_candidate ? `${route}/candidates/${encodeURIComponent(draft.based_on_candidate)}/revisions` : `${route}/candidates`, { method: 'POST', body: payload }); await onDone(); }
    catch (err) { setError(err); if (err.status >= 400 && err.status < 500 && err.status !== 408) update('submitted_payload', null); }
    finally { setBusy(false); }
  }
  return <Modal title={draft.based_on_candidate ? '기존 후보의 수정안 작성' : draft.from_record ? '확정 기록의 후속 변경' : '회의·작업 기록 작성'} eyebrow="SOURCE → CONTEXT → REVIEW" wide busy={busy} onClose={onClose}><form onSubmit={submit}><div className="modal-body ctx-editor"><p className="form-intro">회의록·대화 또는 완료한 작업의 판단 과정을 남겨주세요. 검토 후보로 저장되며, 확정 후 프로젝트 기록으로 확정합니다.</p>{draft.based_on_candidate ? <Notice className="notice subtle"><p>최신 기준을 확인해 새 수정안으로 등록합니다. 이전 후보는 수정안으로 교체되며, 이전 내용과 검토 이력은 보존됩니다.</p></Notice> : null}{draft.expected_context_version !== version ? <Notice className="notice warning"><AlertTriangle size={17} /><div><p>작성 중 프로젝트 기준이 v{version}으로 바뀌었습니다. 기존 기준·충돌 내용을 확인한 뒤 갱신해 주세요.</p><Button type="button" variant="secondary" disabled={locked} onClick={() => update('expected_context_version', version)}>확인 후 최신 기준으로 갱신</Button></div></Notice> : null}<fieldset disabled={locked} className="ctx-editor-fields"><legend className="sr-only">기록 내용</legend><div className="form-columns"><FormField label="기록 종류"><Select value={draft.kind} onChange={(event) => update('kind', event.target.value)}>{Object.entries(KINDS).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</Select></FormField><FormField label="업무 영역"><Select value={draft.domain_id} onChange={(event) => update('domain_id', event.target.value)}><option value="">프로젝트 공통</option>{domains.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></FormField></div><FormField label="제목"><Input value={draft.title} onChange={(event) => update('title', event.target.value)} required maxLength={300} placeholder="예: 가입 인증 수단을 이메일로 확정한 이유" /></FormField><div className="form-columns"><FormField label="발생·결정 시각 (한국 시간)"><Input type="datetime-local" step="1" value={draft.occurred_at} onChange={(event) => update('occurred_at', event.target.value)} required /></FormField><FormField label="대화 채널·기록 경로"><Input value={draft.channel} onChange={(event) => update('channel', event.target.value)} required maxLength={200} placeholder="대면 회의 / Slack / 이메일 / STT 변환본" /></FormField></div><FormField label={draft.kind === 'retrospective' ? '작업 결과와 진행 과정' : '내용'} hint={draft.kind === 'meeting' ? '회의록이나 이미 변환된 STT 텍스트를 붙여 넣을 수 있습니다. 음성 파일을 자동 변환하지는 않습니다.' : '결정 내용, 적용 범위, 결과를 구체적으로 기록해 주세요.'}><Textarea value={draft.body} onChange={(event) => update('body', event.target.value)} required rows={7} maxLength={30000} placeholder={draft.kind === 'retrospective' ? '수행한 작업, 문제 상황, 해결 방법, 남은 과제' : '회의·대화 내용 또는 기록할 요구사항·결정사항'} /></FormField><div className="form-columns"><FormField label="고객 합의 상태" hint="내부 검토 확정과 고객 합의는 별도로 기록합니다."><Select value={draft.certainty || 'proposed'} onChange={(event) => update('certainty', event.target.value)}>{Object.entries(CERTAINTIES).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</Select></FormField><FormField label="기존 계약·요구사항 범위"><Select value={draft.scope || 'unknown'} onChange={(event) => update('scope', event.target.value)}>{Object.entries(SCOPES).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</Select></FormField></div><FormField label="판단 이유·근거" hint="무엇을 결정했는지와 함께 왜 그렇게 판단했는지 남깁니다."><Textarea value={draft.rationale} onChange={(event) => update('rationale', event.target.value)} required={['decision', 'retrospective', 'knowledge'].includes(draft.kind)} rows={3} maxLength={10000} placeholder="고려한 제약, 고객의 설명, 비교 결과, 테스트 근거 등" /></FormField>
      <Disclosure className="ctx-editor-details" open={draft.alternatives.length > 0}><summary>검토한 대안 · {draft.alternatives.length}개</summary>{draft.alternatives.map((entry, index) => <section className="ctx-edit-row" key={index}><header><strong>대안 {index + 1}</strong><ControlButton type="button" className="icon-button" aria-label={`대안 ${index + 1} 삭제`} onClick={() => removeEntry('alternatives', index)}><X size={14} /></ControlButton></header><div className="form-columns"><FormField label="대안 내용"><Input required value={entry.title} onChange={(event) => updateEntry('alternatives', index, 'title', event.target.value)} maxLength={500} /></FormField><FormField label="판단"><Select value={entry.status} onChange={(event) => updateEntry('alternatives', index, 'status', event.target.value)}><option value="chosen">채택</option><option value="rejected">폐기</option><option value="deferred">보류</option></Select></FormField></div><FormField label="판단 이유"><Textarea required rows={2} value={entry.reason} onChange={(event) => updateEntry('alternatives', index, 'reason', event.target.value)} maxLength={3000} /></FormField></section>)}<Button type="button" variant="secondary" icon={Plus} disabled={draft.alternatives.length >= 20} onClick={() => update('alternatives', [...draft.alternatives, { title: '', status: 'chosen', reason: '' }])}>대안 추가</Button></Disclosure>
      <Disclosure className="ctx-editor-details" open={draft.questions.length > 0}><summary>추가 확인할 질문 · {draft.questions.length}개</summary>{draft.questions.map((entry, index) => <section className="ctx-edit-row" key={index}><header><strong>질문 {index + 1}</strong><ControlButton type="button" className="icon-button" aria-label={`질문 ${index + 1} 삭제`} onClick={() => removeEntry('questions', index)}><X size={14} /></ControlButton></header><FormField label="질문"><Input required value={entry.text} onChange={(event) => updateEntry('questions', index, 'text', event.target.value)} maxLength={2000} /></FormField><FormField label="확인한 답변 (선택)"><Textarea rows={2} value={entry.answer} onChange={(event) => updateEntry('questions', index, 'answer', event.target.value)} maxLength={5000} /></FormField><label className="ctx-check"><Input type="checkbox" checked={entry.blocking} onChange={(event) => updateEntry('questions', index, 'blocking', event.target.checked)} />이 질문의 답변을 확인해야 확정할 수 있음</label></section>)}<Button type="button" variant="secondary" icon={Plus} disabled={draft.questions.length >= 20} onClick={() => update('questions', [...draft.questions, { text: '', answer: '', blocking: true }])}>질문 추가</Button></Disclosure>
      <Disclosure className="ctx-editor-details" open={Boolean(draft.entity_key || conflictIds.length)}><summary>기존 기준과 연결 · 충돌 확인</summary><FormField label="같은 요구사항·결정을 구분하는 주제 키" hint="같은 업무 영역에서 같은 주제 키를 사용하면 기존 기준과의 충돌을 확인합니다. 예: 회원가입.인증수단"><Input value={draft.entity_key} onChange={(event) => update('entity_key', event.target.value)} maxLength={200} placeholder="예: 회원가입.인증수단" /></FormField><FormField label="대체할 기존 기준 (선택)"><Select value={draft.supersedes_id} onChange={(event) => update('supersedes_id', event.target.value)}><option value="">새로운 기록으로 추가</option>{records.filter((item) => item.status !== 'superseded' && (item.domain_id || '') === draft.domain_id).map((item) => <option value={item.id} key={item.id}>{item.title} · v{item.context_version}</option>)}</Select></FormField>{conflictIds.map((id) => { const entry = conflictValue(id), record = records.find((item) => item.id === id); return <section key={id} className="ctx-edit-row"><h4>{record?.title || '기존 기준과의 관계'}</h4>{record?.body ? <p>{record.body}</p> : null}<FormField label="함께 적용할 수 있나요?"><Select value={entry.resolution} onChange={(event) => changeConflict(id, 'resolution', event.target.value)}><option value="unresolved">아직 확인하지 않음</option><option value="supersede">기존 기준을 새 내용으로 대체</option><option value="coexist">적용 조건을 나누어 함께 유지</option></Select></FormField><FormField label="해결 근거·적용 조건"><Textarea value={entry.reason} required={entry.resolution !== 'unresolved'} rows={2} maxLength={3000} onChange={(event) => changeConflict(id, 'reason', event.target.value)} /></FormField></section>; })}</Disclosure>
      <section className="ctx-source-picker"><h4>원문 근거 연결</h4><p className="ctx-help">등록된 문서·작업·대화 중 이번 판단의 근거를 선택하세요.</p>{draft.source_refs.length ? <div className="ctx-selected-sources">{draft.source_refs.map((ref) => <span key={sourceKey(ref)}>{SOURCE_TYPES[ref.type] || '근거'} · {String(ref.id).slice(0, 8)}<ControlButton type="button" aria-label="선택한 근거 제거" className="icon-button" onClick={() => update('source_refs', draft.source_refs.filter((entry) => sourceKey(entry) !== sourceKey(ref)))}><X size={12} /></ControlButton></span>)}</div> : null}<div className="ctx-source-search"><Input maxLength={500} value={sourceQuery} onChange={(event) => setSourceQuery(event.target.value)} placeholder="근거 자료 검색" aria-label="근거 자료 검색" onKeyDown={(event) => { if (event.key === 'Enter') { event.preventDefault(); setSourceSearch(sourceQuery.trim()); setSourceOffset(0); } }} /><Button type="button" variant="secondary" icon={Search} onClick={() => { setSourceSearch(sourceQuery.trim()); setSourceOffset(0); }}>찾기</Button></div><ErrorNotice error={sources.error} />{sources.loading ? <Spinner label="근거 자료를 불러오고 있습니다" /> : sources.data?.items?.length ? <>{sources.data.items.filter((source) => ['revision', 'commercial_revision', 'work_item', 'channel_inbox', 'context_record', 'transcription', 'question', 'work_artifact'].includes(source.internal_ref?.type || source.type)).map((source) => { const ref = source.internal_ref || source; return <label className="ctx-source-option" key={sourceKey(ref)}><Input type="checkbox" checked={selectedRefs.has(sourceKey(ref))} disabled={!selectedRefs.has(sourceKey(ref)) && draft.source_refs.length >= 20} onChange={() => chooseSource(source)} /><span><strong>{source.title}</strong><small>{SOURCE_TYPES[ref.type]} · {STATUS_LABELS[source.status] || (source.approved ? '승인된 자료' : '미확정 자료')}</small></span></label>; })}<Pagination offset={sourceOffset} pageSize={10} data={sources.data} setOffset={setSourceOffset} /></> : <p className="ctx-help">연결할 자료가 없습니다. 직접 작성한 내용도 담당자의 기록으로 검토할 수 있습니다.</p>}</section>{draft.kind === 'knowledge' ? <p className="ctx-help"><ShieldCheck size={14} /> 검토 후에도 이 프로젝트 안에서만 조회·재사용합니다.</p> : null}</fieldset>{attempted && !busy ? <Notice className="notice warning"><AlertTriangle size={17} /><p>처리 결과를 확인하지 못했습니다. 다시 시도하면 같은 요청으로 확인합니다. 입력은 이 화면에 유지됩니다.</p></Notice> : null}<ErrorNotice error={error} /></div><footer className="modal-actions"><Button type="button" variant="secondary" disabled={locked} onClick={onDiscard}>작성 내용 비우기</Button><Button type="button" variant="secondary" disabled={busy} onClick={onClose}>닫고 작성 내용 유지</Button><Button type="submit" busy={busy} icon={GitMerge} disabled={!draft.title.trim() || !draft.body.trim() || (!attempted && draft.expected_context_version !== version)}>{attempted ? '같은 요청으로 다시 시도' : '검토 후보로 등록'}</Button></footer></form></Modal>;
}

export function ContextSourceDetail({ route, request, sourceRef, onClose, onOpenRecord, onOpenWorkItem }) {
  const [revision, setRevision] = useState(0);
  const result = useContextData(request, `${route}/sources/${encodeURIComponent(sourceRef.type)}/${encodeURIComponent(sourceRef.id)}`, revision);
  const source = result.data?.source;
  return <Modal title={source?.title || '원문 근거'} eyebrow="SOURCE EVIDENCE" wide onClose={onClose}><div className="modal-body ctx-detail"><ErrorNotice error={result.error} onRetry={() => setRevision((value) => value + 1)} />{result.loading ? <Spinner label="원문 근거를 확인하고 있습니다" /> : source ? <><div className="ctx-detail-meta"><span>{SOURCE_TYPES[sourceRef.type]}</span><ContextStatus status={source.status} approved={source.approved} /></div><dl className="ctx-time-fields"><dt>발생 시각</dt><dd>{occurredLabel(source)} KST</dd><dt>등록 시각</dt><dd>{preciseTime(source.recorded_at)} KST</dd></dl><div className="ctx-body-text">{source.text || '추출된 원문이 없습니다.'}</div><div className="ctx-detail-section"><SourceLink source={{ ...source, internal_ref: sourceRef }} onOpenRecord={onOpenRecord} onOpenWorkItem={onOpenWorkItem} />{source.sha256 ? <Disclosure className="ctx-source-fingerprint"><summary>근거 버전 식별값</summary><code>{source.sha256}</code></Disclosure> : null}</div></> : null}</div><footer className="modal-actions"><Button variant="secondary" onClick={onClose}>닫기</Button></footer></Modal>;
}

function KnowledgeImport({ project, request, route, version, domains, draft, setDraft, onClose, onDiscard, onDone }) {
  const projects = useContextData(request, '/api/projects', 0);
  const sources = useContextData(request, draft.source_project_id ? `${projectPath(draft.source_project_id)}/context` : null, 0);
  const [busy, setBusy] = useState(false), [sourceLoading, setSourceLoading] = useState(false), [error, setError] = useState(null), [acknowledged, setAcknowledged] = useState(false);
  const sourceSequence = useRef(0);
  useEffect(() => () => { sourceSequence.current += 1; }, []);
  const attempted = Boolean(draft.submitted_payload), locked = busy || sourceLoading || attempted;
  const availableProjects = (projects.data?.projects || []).filter((item) => item.id !== project.id && ['owner', 'reviewer'].includes(item.role));
  const knowledge = (sources.data?.records || []).filter((item) => item.kind === 'knowledge' && item.status !== 'superseded' && !item.evidence_changed);
  function update(field, value) { setDraft((old) => ({ ...old, [field]: value })); setAcknowledged(false); }
  async function selectRecord(recordId) {
    if (!recordId) { update('source_record_id', ''); return; }
    const seq = ++sourceSequence.current; setSourceLoading(true); setError(null); setAcknowledged(false);
    try {
      const result = await request(`${projectPath(draft.source_project_id)}/context/sources/context_record/${encodeURIComponent(recordId)}`);
      if (seq !== sourceSequence.current) return;
      const record = knowledge.find((item) => item.id === recordId), source = result.source;
      if (!source.approved) throw new Error('원본 지식의 근거 또는 승인 상태가 바뀌었습니다. 다른 확정 지식을 선택해 주세요.');
      setDraft((old) => ({ ...old, source_record_id: recordId, source_sha256: source.sha256, title: record?.title || source.title, body: record?.body || source.text, rationale: '', source_preview: source.text, expected_context_version: version }));
    } catch (err) { if (seq === sourceSequence.current) setError(err); }
    finally { if (seq === sourceSequence.current) setSourceLoading(false); }
  }
  async function submit(event) {
    event.preventDefault(); setBusy(true); setError(null);
    const payload = draft.submitted_payload || { request_id: draft.request_id, source_project_id: draft.source_project_id, source_record_id: draft.source_record_id, source_sha256: draft.source_sha256, expected_context_version: draft.expected_context_version, title: draft.title.trim(), body: draft.body.trim(), rationale: draft.rationale.trim(), domain_id: draft.domain_id || null, occurred_at: isoKst(draft.occurred_at) };
    setDraft((old) => ({ ...old, submitted_payload: payload }));
    try { await request(`${route}/knowledge/import`, { method: 'POST', body: payload }); await onDone(); }
    catch (err) { setError(err); if (err.status >= 400 && err.status < 500 && err.status !== 408) setDraft((old) => ({ ...old, submitted_payload: null })); }
    finally { setBusy(false); }
  }
  return <Modal title="다른 프로젝트 지식 가져오기" eyebrow="REVIEWED KNOWLEDGE TRANSFER" wide busy={busy || sourceLoading} onClose={onClose}><form onSubmit={submit}><div className="modal-body ctx-editor"><p className="form-intro">원본 프로젝트의 검토 권한이 있는 지식만 선택할 수 있습니다. 이 프로젝트에 전달해도 되는 내용으로 수정한 뒤 검토 후보로 등록하세요.</p><ErrorNotice error={projects.error || sources.error} /><fieldset className="ctx-editor-fields" disabled={locked}><legend className="sr-only">프로젝트 지식 선택·수정</legend><FormField label="원본 프로젝트"><Select value={draft.source_project_id} onChange={(event) => { sourceSequence.current += 1; setDraft((old) => ({ ...old, source_project_id: event.target.value, source_record_id: '', source_sha256: '', title: '', body: '', rationale: '', source_preview: '' })); setAcknowledged(false); }} required><option value="">검토 권한이 있는 프로젝트 선택</option>{availableProjects.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</Select></FormField>{!projects.loading && !availableProjects.length ? <p className="ctx-help">다른 프로젝트의 관리자·검토자 권한이 필요합니다.</p> : null}<FormField label="검토 확정된 프로젝트 지식" hint="원본 프로젝트의 최근 확정 기록에서 지식을 표시합니다."><Select value={draft.source_record_id} onChange={(event) => selectRecord(event.target.value)} required disabled={!draft.source_project_id || sources.loading}><option value="">가져올 지식 선택</option>{knowledge.map((item) => <option value={item.id} key={item.id}>{item.title}</option>)}</Select></FormField>{sourceLoading ? <Spinner label="원본 지식과 승인 상태를 확인하고 있습니다" /> : null}{draft.source_record_id ? <><Disclosure className="ctx-editor-details"><summary>원본 지식 대조</summary><div className="ctx-body-text">{draft.source_preview}</div></Disclosure><FormField label="이 프로젝트에 전달할 제목"><Input required value={draft.title} maxLength={300} onChange={(event) => update('title', event.target.value)} /></FormField><FormField label="이 프로젝트에 전달할 내용" hint="고객명·내부 수치·기밀 정보 등 재사용하지 않을 내용을 제외하세요. 아래 작성한 내용이 검토 후보에 저장됩니다."><Textarea required rows={7} maxLength={30000} value={draft.body} onChange={(event) => update('body', event.target.value)} /></FormField><FormField label="재사용 근거·적용 조건"><Textarea required rows={3} maxLength={10000} value={draft.rationale} onChange={(event) => update('rationale', event.target.value)} placeholder="원본 프로젝트의 경험을 여기서 적용할 수 있는 이유와 다른 조건" /></FormField><div className="form-columns"><FormField label="대상 업무 영역"><Select value={draft.domain_id} onChange={(event) => update('domain_id', event.target.value)}><option value="">프로젝트 공통</option>{domains.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</Select></FormField><FormField label="재사용 판단 시각 (한국 시간)"><Input type="datetime-local" step="1" required value={draft.occurred_at} onChange={(event) => update('occurred_at', event.target.value)} /></FormField></div><label className="ctx-check"><Input type="checkbox" checked={acknowledged} onChange={(event) => setAcknowledged(event.target.checked)} />원본 지식의 사용 조건과 이 프로젝트에 전달할 내용을 확인했습니다.</label></> : null}</fieldset>{draft.expected_context_version !== version ? <Notice className="notice warning"><p>대상 프로젝트 기준이 v{version}으로 변경되었습니다. 적용 조건을 다시 확인한 뒤 갱신하세요.</p><ControlButton type="button" className="text-button" disabled={locked} onClick={() => update('expected_context_version', version)}>확인 후 기준 갱신</ControlButton></Notice> : null}{attempted && !busy ? <Notice className="notice warning"><p>처리 응답을 확인하지 못했습니다. 같은 요청으로 다시 확인할 수 있습니다.</p></Notice> : null}<ErrorNotice error={error} /></div><footer className="modal-actions"><Button type="button" variant="secondary" disabled={locked} onClick={onDiscard}>작성 내용 비우기</Button><Button type="button" variant="secondary" disabled={busy || sourceLoading} onClick={onClose}>닫고 작성 내용 유지</Button><Button type="submit" icon={GitMerge} busy={busy} disabled={!draft.source_record_id || (!attempted && (!acknowledged || !draft.title.trim() || !draft.body.trim() || !draft.rationale.trim() || draft.expected_context_version !== version))}>{attempted ? '같은 요청으로 확인' : '검토 후보로 가져오기'}</Button></footer></form></Modal>;
}
